QString resourceRoot() {
    const auto app = QCoreApplication::applicationDirPath();
    for (auto root : {app + "/../Resources", app + "/resources", QString(CF_SOURCE_DIR)})
        if (QFileInfo::exists(root + "/runtime/main.c")) return QDir(root).absolutePath();
    return {};
}
static QString literal(QString s) {
    s.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n").replace("?", "\\?");
    for(int i=1;i<32;++i)s.replace(QChar(i),QString("\\%1").arg(i,3,8,QChar('0')));
    return "\"" + s + "\"";
}
// Independent 64-byte blocks bound random-access decode work and RAM use.
EncodedResource encodeResource(const QByteArray &raw){
    QByteArray packed((raw.size()+63)/64*2,0);
    for(int offset=0,block=0;offset<raw.size();offset+=64,++block){
        const int address=packed.size();packed[block*2]=char(address);packed[block*2+1]=char(address>>8);
        const auto bytes=raw.mid(offset,64);int i=0;
        auto run=[&](int at){int n=1;while(at+n<bytes.size()&&bytes[at+n]==bytes[at]&&n<128)++n;return n;};
        while(i<bytes.size()){
            int n=run(i);if(n>=3){packed.append(char(128|(n-1)));packed.append(bytes[i]);i+=n;}
            else{int start=i;i+=n;while(i<bytes.size()&&run(i)<3)i+=run(i);packed.append(char(i-start-1));packed.append(bytes.mid(start,i-start));}
        }
    }
    return packed.size()<raw.size()?EncodedResource{packed,1}:EncodedResource{raw,0};
}
struct BankWriter {
    int bank=4,used=0;QMap<int,QString> files;QString declarations;int resourceRaw=0,resourceStored=0;bool soundUsed=false;
    int add(const QString &definition,int bytes){if(used+bytes>16384){++bank;used=0;}used+=bytes;files[bank]+=definition+"\n";return bank;}
};
